create type public.payroll_status as enum('pending','partial','paid','cancelled');
create type public.month_close_status as enum('open','closed');
create table public.salary_configs(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id),base_salary numeric(18,2)not null check(base_salary>=0),currency public.currency_code not null default'TRY',effective_from date not null,effective_to date,notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),exclude using gist(profile_id with =,daterange(effective_from,coalesce(effective_to+1,'infinity'::date),'[)')with&&));
create table public.payroll_periods(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id),year integer not null check(year between 2000 and 2200),month integer not null check(month between 1 and 12),employment_type public.employment_type not null,base_salary numeric(18,2)not null default 0,commission numeric(18,2)not null default 0,bonus numeric(18,2)not null default 0,advance numeric(18,2)not null default 0,deduction numeric(18,2)not null default 0,other numeric(18,2)not null default 0,net_payable numeric(18,2)generated always as(base_salary+commission+bonus+other-advance-deduction)stored,currency public.currency_code not null,status public.payroll_status not null default'pending',notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(profile_id,year,month));
create table public.payroll_payments(id uuid primary key default gen_random_uuid(),payroll_period_id uuid not null references public.payroll_periods(id),account_id uuid not null references public.accounts(id),amount numeric(18,2)not null check(amount>0),currency public.currency_code not null,payment_date date not null,transaction_id uuid not null unique references public.finance_transactions(id),notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.partner_ownerships(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id),ownership_percent numeric(7,4)not null check(ownership_percent>0 and ownership_percent<=100),effective_from date not null,effective_to date,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from),exclude using gist(profile_id with =,daterange(effective_from,coalesce(effective_to+1,'infinity'::date),'[)')with&&));
create table public.month_closes(id uuid primary key default gen_random_uuid(),year integer not null check(year between 2000 and 2200),month integer not null check(month between 1 and 12),status public.month_close_status not null default'open',reserve_amount numeric(18,2)not null default 0,notes text,snapshot jsonb,closed_by uuid references public.profiles(id),closed_at timestamptz,reopened_by uuid references public.profiles(id),reopened_at timestamptz,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(year,month));
create table public.month_close_checklist(id uuid primary key default gen_random_uuid(),month_close_id uuid not null references public.month_closes(id)on delete cascade,item_key text not null,label text not null,position integer not null,is_completed boolean not null default false,completed_by uuid references public.profiles(id),completed_at timestamptz,unique(month_close_id,item_key));
create table public.profit_distributions(id uuid primary key default gen_random_uuid(),month_close_id uuid not null references public.month_closes(id),profile_id uuid not null references public.profiles(id),ownership_percent numeric(7,4)not null,amount numeric(18,2)not null,currency public.currency_code not null default'TRY',status public.payroll_status not null default'pending',created_at timestamptz not null default now(),unique(month_close_id,profile_id));
create trigger set_updated_at before update on public.payroll_periods for each row execute function public.set_updated_at();create trigger set_updated_at before update on public.month_closes for each row execute function public.set_updated_at();
insert into public.permissions(key,name,module)values('payroll.read','Maaşları görüntüle','payroll'),('payroll.manage','Maaşları yönet','payroll'),('month_close.read','Ay kapanışını görüntüle','month_close'),('month_close.manage','Ay kapanışını yönet','month_close'),('month_close.reopen','Kapalı ayı yeniden aç','month_close')on conflict(key)do nothing;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where r.slug='super-admin'and p.module in('payroll','month_close')on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where r.slug in('partner','accounting')and p.key in('payroll.read','payroll.manage','month_close.read','month_close.manage')on conflict do nothing;
alter table public.salary_configs enable row level security;alter table public.payroll_periods enable row level security;alter table public.payroll_payments enable row level security;alter table public.partner_ownerships enable row level security;alter table public.month_closes enable row level security;alter table public.month_close_checklist enable row level security;alter table public.profit_distributions enable row level security;
create policy salary_read on public.salary_configs for select to authenticated using(public.has_permission('payroll.read'));create policy salary_manage on public.salary_configs for all to authenticated using(public.has_permission('payroll.manage'))with check(public.has_permission('payroll.manage'));create policy payroll_read on public.payroll_periods for select to authenticated using(public.has_permission('payroll.read'));create policy payroll_manage on public.payroll_periods for all to authenticated using(public.has_permission('payroll.manage'))with check(public.has_permission('payroll.manage'));create policy payroll_payments_read on public.payroll_payments for select to authenticated using(public.has_permission('payroll.read'));create policy payroll_payments_insert on public.payroll_payments for insert to authenticated with check(public.has_permission('payroll.manage')and created_by=auth.uid());create policy ownership_read on public.partner_ownerships for select to authenticated using(public.has_permission('month_close.read'));create policy ownership_manage on public.partner_ownerships for all to authenticated using(public.has_permission('month_close.manage'))with check(public.has_permission('month_close.manage'));create policy month_close_access on public.month_closes for all to authenticated using(public.has_permission('month_close.read'))with check(public.has_permission('month_close.manage'));create policy checklist_access on public.month_close_checklist for all to authenticated using(public.has_permission('month_close.read'))with check(public.has_permission('month_close.manage'));create policy distributions_access on public.profit_distributions for all to authenticated using(public.has_permission('month_close.read'))with check(public.has_permission('month_close.manage'));
create or replace function public.initialize_month_close(p_year integer,p_month integer)returns uuid language plpgsql security invoker set search_path=''as $$declare close_id uuid;labels text[][]:=array[['invoices','Tüm faturalar kontrol edildi'],['collections','Tüm tahsilatlar kontrol edildi'],['overdue','Gecikmiş ödemeler değerlendirildi'],['vendor_accruals','Tedarikçi hakedişleri girildi'],['vendor_payments','Tedarikçi ödemeleri yapıldı'],['employee_payroll','Personel maaşları yatırıldı'],['partner_payroll','Ortak maaşları yatırıldı'],['expenses','Şirket giderleri girildi'],['accounts','Kasalar kontrol edildi'],['profit','Dönem kârı hesaplandı'],['distributable','Dağıtılabilir kâr belirlendi'],['distribution','Ortaklara kâr dağıtımı yapıldı']];i integer;begin if not public.has_permission('month_close.manage')then raise exception'insufficient_permission'using errcode='42501';end if;insert into public.month_closes(year,month,created_by)values(p_year,p_month,auth.uid())on conflict(year,month)do update set year=excluded.year returning id into close_id;for i in 1..array_length(labels,1)loop insert into public.month_close_checklist(month_close_id,item_key,label,position)values(close_id,labels[i][1],labels[i][2],i)on conflict(month_close_id,item_key)do nothing;end loop;return close_id;end$$;
create or replace function public.generate_payroll_periods(p_year integer,p_month integer)returns integer language plpgsql security invoker set search_path=''as $$declare p record;period_start date:=make_date(p_year,p_month,1);created_count integer:=0;begin if not public.has_permission('payroll.manage')then raise exception'insufficient_permission'using errcode='42501';end if;for p in select pr.id,pr.employment_type,sc.base_salary,sc.currency from public.profiles pr join lateral(select*from public.salary_configs x where x.profile_id=pr.id and x.effective_from<=period_start and(x.effective_to is null or x.effective_to>=period_start)order by x.effective_from desc limit 1)sc on true where pr.status='active'and pr.employment_type in('employee','partner')loop insert into public.payroll_periods(profile_id,year,month,employment_type,base_salary,currency,created_by)values(p.id,p_year,p_month,p.employment_type,p.base_salary,p.currency,auth.uid())on conflict(profile_id,year,month)do nothing;if found then created_count:=created_count+1;end if;end loop;return created_count;end$$;
create or replace function public.pay_payroll(p_payroll_id uuid,p_account_id uuid,p_amount numeric,p_payment_date date,p_notes text)returns uuid language plpgsql security invoker set search_path=''as $$declare payroll public.payroll_periods%rowtype;account_currency public.currency_code;paid numeric;tx_id uuid;payment_id uuid;new_status public.payroll_status;begin if not(public.has_permission('payroll.manage')and public.has_permission('accounts.manage'))then raise exception'insufficient_permission'using errcode='42501';end if;select*into payroll from public.payroll_periods where id=p_payroll_id for update;if not found then raise exception'payroll_not_found';end if;if exists(select 1 from public.month_closes where year=payroll.year and month=payroll.month and status='closed')then raise exception'period_closed';end if;select currency into account_currency from public.accounts where id=p_account_id and status='active';if account_currency is null or account_currency<>payroll.currency then raise exception'currency_mismatch_or_account_missing';end if;select coalesce(sum(amount),0)into paid from public.payroll_payments where payroll_period_id=p_payroll_id;if p_amount<=0 or paid+p_amount>payroll.net_payable then raise exception'invalid_payment_amount';end if;insert into public.finance_transactions(account_id,transaction_date,transaction_type,amount,currency,category,description,created_by)values(p_account_id,p_payment_date,'expense',-p_amount,payroll.currency,case when payroll.employment_type='partner'then'Ortak maaşı'else'Personel maaşı'end,p_notes,auth.uid())returning id into tx_id;insert into public.payroll_payments(payroll_period_id,account_id,amount,currency,payment_date,transaction_id,notes,created_by)values(p_payroll_id,p_account_id,p_amount,payroll.currency,p_payment_date,tx_id,p_notes,auth.uid())returning id into payment_id;paid:=paid+p_amount;new_status:=case when paid>=payroll.net_payable then'paid'::public.payroll_status else'partial'::public.payroll_status end;update public.payroll_periods set status=new_status where id=p_payroll_id;return payment_id;end$$;
create or replace function public.close_month(p_close_id uuid,p_reserve numeric,p_notes text)returns void language plpgsql security invoker set search_path=''as $$declare c public.month_closes%rowtype;s jsonb;profit numeric;ownership_total numeric;begin if not public.has_permission('month_close.manage')then raise exception'insufficient_permission'using errcode='42501';end if;select*into c from public.month_closes where id=p_close_id for update;if c.status='closed'then raise exception'already_closed';end if;if exists(select 1 from public.month_close_checklist where month_close_id=p_close_id and not is_completed)then raise exception'checklist_incomplete';end if;select jsonb_build_object('accrual_revenue',coalesce((select sum(net_amount)from public.service_periods where year=c.year and month=c.month),0),'cash_collections',coalesce((select sum(amount)from public.payments where extract(year from payment_date)=c.year and extract(month from payment_date)=c.month),0),'vendor_costs',coalesce((select sum(amount)from public.vendor_accruals where year=c.year and month=c.month and status<>'cancelled'),0),'payroll_costs',coalesce((select sum(net_payable)from public.payroll_periods where year=c.year and month=c.month and status<>'cancelled'),0),'account_balances',(select coalesce(jsonb_object_agg(a.name,b.balance),'{}'::jsonb)from public.account_balances()b join public.accounts a on a.id=b.account_id))into s;profit:=(s->>'accrual_revenue')::numeric-(s->>'vendor_costs')::numeric-(s->>'payroll_costs')::numeric-p_reserve;select coalesce(sum(ownership_percent),0)into ownership_total from public.partner_ownerships where effective_from<=make_date(c.year,c.month,1)and(effective_to is null or effective_to>=make_date(c.year,c.month,1));if profit>0 and abs(ownership_total-100)>0.0001 then raise exception'ownership_total_must_be_100';end if;s:=s||jsonb_build_object('reserve_amount',p_reserve,'distributable_profit',greatest(profit,0));delete from public.profit_distributions where month_close_id=p_close_id;insert into public.profit_distributions(month_close_id,profile_id,ownership_percent,amount)select p_close_id,profile_id,ownership_percent,round(greatest(profit,0)*ownership_percent/100,2)from public.partner_ownerships where effective_from<=make_date(c.year,c.month,1)and(effective_to is null or effective_to>=make_date(c.year,c.month,1));update public.month_closes set status='closed',reserve_amount=p_reserve,notes=p_notes,snapshot=s,closed_by=auth.uid(),closed_at=now()where id=p_close_id;end$$;
create or replace function public.reopen_month(p_close_id uuid)returns void language plpgsql security invoker set search_path=''as $$begin if not public.has_permission('month_close.reopen')then raise exception'insufficient_permission'using errcode='42501';end if;update public.month_closes set status='open',reopened_by=auth.uid(),reopened_at=now()where id=p_close_id;end$$;
grant execute on function public.initialize_month_close(integer,integer)to authenticated;grant execute on function public.generate_payroll_periods(integer,integer)to authenticated;grant execute on function public.pay_payroll(uuid,uuid,numeric,date,text)to authenticated;grant execute on function public.close_month(uuid,numeric,text)to authenticated;grant execute on function public.reopen_month(uuid)to authenticated;
